class KitchenOrdersPage extends StatefulWidget { const KitchenOrdersPage({super.key}); @override State<KitchenOrdersPage> createState()=>_KitchenOrdersPageState(); }
class _KitchenOrdersPageState extends State<KitchenOrdersPage> {
