  @override Widget build(BuildContext context){
    return Column(children:[_header('Pedidos y cocina','Controla el avance de cada comanda',null),Padding(padding:const EdgeInsets.fromLTRB(16,0,16,10),child:Row(children:[Expanded(child:DropdownButtonFormField<String>(value:status,decoration:const InputDecoration(labelText:'Estado',isDense:true),items:statuses.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)setState(()=>status=v);load();})),const SizedBox(width:10),Expanded(child:DropdownButtonFormField<String>(value:service,decoration:const InputDecoration(labelText:'Servicio',isDense:true),items:services.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)setState(()=>service=v);load();}))])),Expanded(child:loading?const Center(child:CircularProgressIndicator()):orders.isEmpty?const Center(child:Text('No hay pedidos para estos filtros.')):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.fromLTRB(12,0,12,16),itemCount:orders.length,itemBuilder:(ctx,i){final o=orders[i];final current='${o['estado_actual']??'Pendiente'}';return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[Expanded(child:Text('${o['numero']}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16))),Container(padding:const EdgeInsets.symmetric(horizontal:9,vertical:5),decoration:BoxDecoration(color:statusColor(current).withValues(alpha:.12),borderRadius:BorderRadius.circular(20)),child:Text(current,style:TextStyle(color:statusColor(current),fontWeight:FontWeight.bold,fontSize:12)))]),const SizedBox(height:5),Text('${o['tipo_servicio']??'Local'}${o['mesa']==null?'':' · Mesa ${o['mesa']}'} · ${o['fecha']}'),Text('Total: Q${(o['total'] as num).toStringAsFixed(2)}'),Row(children:[TextButton.icon(onPressed:()=>details(o),icon:const Icon(Icons.receipt_long),label:const Text('Ver comanda')),const Spacer(),PopupMenuButton<String>(tooltip:'Cambiar estado',onSelected:(v)=>changeStatus(o,v),itemBuilder:(ctx)=>statuses.where((v)=>v!='Todos').map((v)=>PopupMenuItem(value:v,child:Text(v))).toList(),child:const Row(children:[Text('Actualizar'),Icon(Icons.arrow_drop_down)]))])])));}))) ]);
