class PurchasesPage extends StatefulWidget { const PurchasesPage({super.key}); @override State<PurchasesPage> createState()=>_PurchasesPageState(); }
class _PurchasesPageState extends State<PurchasesPage> {
  List<Map<String,Object?>> ingredients=[]; List<Map<String,Object?>> suppliers=[]; List<Map<String,Object?>> purchases=[]; List<Map<String,Object?>> expiring=[];
  int? ingredientId; int? supplierId; bool loading=true;
  final qty=TextEditingController(); final cost=TextEditingController(); final lot=TextEditingController(); final expiry=TextEditingController(); final invoice=TextEditingController(); final notes=TextEditingController();
  final lines=<Map<String,Object?>>[];
  @override void initState(){super.initState();load();}
  Future<void> load() async { final db=LocalDatabase.instance; final a=await db.ingredients(); final b=await db.suppliers(); final c=await db.recentIngredientPurchases(); final x=await db.expiringIngredients(days:7); if(!mounted)return; setState((){ingredients=a;suppliers=b;purchases=c;expiring=x;loading=false; if(ingredientId==null&&a.isNotEmpty)ingredientId=a.first['id'] as int;}); }
  double get total=>lines.fold(0,(v,e)=>v+(e['quantity'] as double)*(e['unit_cost'] as double));
  Future<void> addLine(){
    final parsedQty=double.tryParse(qty.text); final parsedCost=double.tryParse(cost.text);
    if(ingredientId==null||parsedQty==null||parsedQty<=0||parsedCost==null||parsedCost<0){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Selecciona un ingrediente e ingresa cantidad y costo válidos.')));return Future.value();}
    final item=ingredients.firstWhere((e)=>e['id']==ingredientId);
    setState((){lines.add({'ingredient_id':ingredientId,'name':item['nombre'],'unit':item['unidad_base'],'quantity':parsedQty,'unit_cost':parsedCost,'lot':lot.text.trim().isEmpty?null:lot.text.trim(),'expiry':expiry.text.trim().isEmpty?null:expiry.text.trim()});qty.clear();cost.clear();lot.clear();expiry.clear();});
    return Future.value();
  }
  Future<void> addSupplier() async {
    final name=TextEditingController(),phone=TextEditingController(),nit=TextEditingController();
    await showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('Nuevo proveedor'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Nombre del proveedor')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Teléfono')),TextField(controller:nit,decoration:const InputDecoration(labelText:'NIT'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancelar')),FilledButton(onPressed:()async{if(name.text.trim().isEmpty)return;await LocalDatabase.instance.saveSupplier(name:name.text.trim(),phone:phone.text.trim(),nit:nit.text.trim());if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Guardar'))]));
    await load();
  }
  Future<void> save() async {
