  @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[_header('Caja y cierre de turno','Control de efectivo, ventas y movimientos',null),if(session==null)...[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Row(children:[Icon(Icons.lock_open,color:AppTheme.aqua),SizedBox(width:8),Text('No hay una caja abierta',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))]),const SizedBox(height:8),const Text('Abre un turno para comenzar a registrar ventas.'),TextField(controller:opening,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Fondo inicial en efectivo Q')),TextField(controller:notes,decoration:const InputDecoration(labelText:'Observaciones (opcional)')),const SizedBox(height:12),FilledButton.icon(onPressed:openCash,icon:const Icon(Icons.lock_open),label:const Text('Abrir caja'))]))) ] else ...[
