class _ReportsPageState extends State<ReportsPage> {
  DateTime start=DateTime(DateTime.now().year,DateTime.now().month,1);
  DateTime end=DateTime.now();
  late Future<Map<String,Object?>> report;
  String period='Mes';
  final money=NumberFormat.currency(locale:'es_GT',symbol:'Q',decimalDigits:2);
  final dateFormat=DateFormat('dd/MM/yyyy');
  @override void initState(){super.initState();load();}
  void load()=>report=LocalDatabase.instance.salesReport(start:start,end:end);
  void preset(String value){final now=DateTime.now();setState((){period=value;end=DateTime(now.year,now.month,now.day);if(value=='Hoy')start=end;else if(value=='7 días')start=end.subtract(const Duration(days:6));else start=DateTime(now.year,now.month,1);load();});}
  Future<void> chooseRange() async {
    final now=DateTime.now();final safeEnd=end.isAfter(now)?now:end;
    final safeStart=start.isAfter(safeEnd)?safeEnd:start;
    final picked=await showDateRangePicker(context:context,firstDate:DateTime(2020),lastDate:now,initialDateRange:DateTimeRange(start:safeStart,end:safeEnd),helpText:'Selecciona el período del reporte');
    if(picked!=null){setState((){period='Personalizado';start=picked.start;end=picked.end;load();});}
  }
  double n(Object? v)=>(v as num? ?? 0).toDouble();
  String q(Object? v)=>money.format(n(v));
  Widget metric(String title,String value,IconData icon)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Icon(icon,color:AppTheme.aqua),Text(value,style:const TextStyle(fontSize:19,fontWeight:FontWeight.bold)),Text(title,style:const TextStyle(color:Colors.black54,fontSize:12))])));
  Widget section(String title,Widget child)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),const SizedBox(height:10),child])));
  Future<void> export(bool asPdf, Map<String,Object?> data) async {
    try {
      final file = asPdf ? await ReportExporter.createPdf(data) : await ReportExporter.createExcel(data);
      if (!mounted) return;
      await ReportExporter.shareFile(file, asPdf ? 'Reporte PDF' : 'Reporte Excel');
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('No se pudo exportar el reporte: $e')));
    }
  }
  @override Widget build(BuildContext context)=>FutureBuilder<Map<String,Object?>>(
    future:report,builder:(context,s){if(s.hasError)return Center(child:Text('No se pudo generar el reporte: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());
      final data=s.data!;final t=data['totals'] as Map<String,Object?>;final daily=(data['daily'] as List).cast<Map<String,Object?>>();final services=(data['services'] as List).cast<Map<String,Object?>>();final payments=(data['payments'] as List).cast<Map<String,Object?>>();final top=(data['top_items'] as List).cast<Map<String,Object?>>();final categories=(data['expense_categories'] as List).cast<Map<String,Object?>>();final purchase=data['purchases'] as Map<String,Object?>;final maxDay=daily.fold<double>(0,(m,r)=>n(r['total'])>m?n(r['total']):m);
      return RefreshIndicator(onRefresh:()async{setState(load);},child:ListView(padding:const EdgeInsets.all(16),children:[
        _header('Reportes del negocio','Ventas, rentabilidad estimada y gastos registrados',null),
        Wrap(spacing:8,runSpacing:8,children:[OutlinedButton.icon(onPressed:()=>export(true,data),icon:const Icon(Icons.picture_as_pdf),label:const Text('Exportar PDF')),OutlinedButton.icon(onPressed:()=>export(false,data),icon:const Icon(Icons.table_view),label:const Text('Exportar Excel'))]),
        Wrap(spacing:8,runSpacing:8,alignment:WrapAlignment.start,children:[ChoiceChip(label:const Text('Hoy'),selected:period=='Hoy',onSelected:(_)=>preset('Hoy')),ChoiceChip(label:const Text('7 días'),selected:period=='7 días',onSelected:(_)=>preset('7 días')),ChoiceChip(label:const Text('Este mes'),selected:period=='Mes',onSelected:(_)=>preset('Mes')),OutlinedButton.icon(onPressed:chooseRange,icon:const Icon(Icons.date_range),label:Text('${dateFormat.format(start)} – ${dateFormat.format(end)}'))]),
        const SizedBox(height:12),
        GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:MediaQuery.sizeOf(context).width>700?4:2,childAspectRatio:1.55,crossAxisSpacing:8,mainAxisSpacing:8,children:[metric('Ventas totales',q(t['revenue']),Icons.payments),metric('Número de ventas','${t['sales_count']??0}',Icons.receipt_long),metric('Costo de recetas',q(t['cost']),Icons.inventory_2),metric('Utilidad bruta estimada',q(t['gross_profit']),Icons.trending_up),metric('Ticket promedio',q(t['average_ticket']),Icons.confirmation_number),metric('Salidas de caja',q(data['cash_outflows']),Icons.money_off),metric('Gastos registrados',q(data['registered_expenses']),Icons.receipt),metric('Compras de ingredientes',q(purchase['total']),Icons.shopping_basket)]),
        const Padding(padding:EdgeInsets.symmetric(vertical:8),child:Text('La utilidad mostrada es estimada y corresponde a ventas menos costo de recetas registrado. No descuenta gastos operativos, impuestos ni otros costos no capturados.',style:TextStyle(color:Colors.black54,fontSize:12))),
        section('Ventas por día',daily.isEmpty?const Text('No hay ventas en este período.'):Column(children:[for(final r in daily)Padding(padding:const EdgeInsets.only(bottom:10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(dateFormat.format(DateTime.parse('${r['day']}')))),Text(q(r['total']),style:const TextStyle(fontWeight:FontWeight.w600))]),const SizedBox(height:4),LinearProgressIndicator(value:maxDay<=0?0:n(r['total'])/maxDay,minHeight:7,borderRadius:BorderRadius.circular(8))]))])),
        section('Ventas por tipo de servicio',services.isEmpty?const Text('Sin datos.'):Column(children:[for(final r in services)ListTile(dense:true,contentPadding:EdgeInsets.zero,title:Text('${r['service']}'),subtitle:Text('${r['count']} ventas'),trailing:Text(q(r['total']),style:const TextStyle(fontWeight:FontWeight.bold)))])),
        section('Métodos de pago',payments.isEmpty?const Text('Sin datos.'):Column(children:[for(final r in payments)ListTile(dense:true,contentPadding:EdgeInsets.zero,title:Text('${r['method']}'),subtitle:Text('${r['count']} ventas'),trailing:Text(q(r['total']),style:const TextStyle(fontWeight:FontWeight.bold)))])),
        section('Platos más vendidos',top.isEmpty?const Text('No hay platos vendidos en este período.'):Column(children:[for(var i=0;i<top.length;i++)ListTile(dense:true,contentPadding:EdgeInsets.zero,leading:CircleAvatar(radius:15,child:Text('${i+1}')),title:Text('${top[i]['name']}'),subtitle:Text('Cantidad: ${n(top[i]['quantity']).toStringAsFixed(2)}'),trailing:Text(q(top[i]['total']),style:const TextStyle(fontWeight:FontWeight.bold)))])),
        section('Gastos registrados por categoría',categories.isEmpty?const Text('No hay gastos registrados en este período.'):Column(children:[for(final r in categories)ListTile(dense:true,contentPadding:EdgeInsets.zero,title:Text('${r['categoria']??'Sin categoría'}'),trailing:Text(q(r['total'])))])),
        section('Compras de ingredientes',Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${purchase['count']??0} compras registradas'),const SizedBox(height:4),Text('Total comprado: ${q(purchase['total'])}',style:const TextStyle(fontWeight:FontWeight.bold))])),
        const SizedBox(height:10),const Text('Los reportes se calculan desde la base de datos local del dispositivo. Para reflejar la operación real, registra todas las ventas, compras y salidas de caja.',style:TextStyle(color:Colors.black54,fontSize:12)),
      ]));
    });
}

